def solve_for_n(n):
    max_k = 0
    for m_min in range(1, n + 1):
        if n - m_min + 1 <= m_min:
            total_f = sum(math.comb(n, j) for j in range(n - m_min + 1, n + 1))
            max_k = max(max_k, total_f // 2)
            continue

        k0 = sum(math.comb(n, m) for m in range(m_min, n - m_min + 1))
        rhs0 = sum(math.comb(n, j) for j in range(n - m_min + 1, n + 1))

        available = [math.comb(n, m) for m in range(n - m_min + 1, n + 1)]
        target = (rhs0 - k0) // 2

        dp = {0}
        for val in available:
            new_dp = set()
            for s in dp:
                if s + val <= target:
                    new_dp.add(s + val)
            dp.update(new_dp)

        max_k = max(max_k, k0 + max(dp))

    return max_k

