def solve_for_n_optimized(n):
    subsets = []
    for i in range(1, 1 << n):
        subsets.append(frozenset([j for j in range(n) if (i >> j) & 1]))

    # For a fixed C (set of complements), 
    # A = {c^c : c \in C}
    # G(A) = {y : y is not a subset of any c in C}
    # k = min(|A|, |G(A) \setminus A|)

    # We want to maximize k.
    # Since we only care about the set G(A), and G(A) only depends on C.
    # If we have two different C1, C2 such that \cup_{c \in C1} \mathcal{P}(c) = \cup_{c \in C2} \mathcal{P}(c),
    # then G(A1) = G(A2).
    # However, A1 and A2 might be different, so |A1 \cap G(A1)| and |A2 \cap G(A2)| might be different.

    # Let's try all possible C where C is a "Sperner family" (no c_i \subseteq c_j).
    # This is because if c_i \subseteq c_j, then \mathcal{P}(c_i) \subseteq \mathcal{P}(c_j),
    # so c_i doesn't affect the union.
    # The number of Sperner families is much smaller.

    sperner_families = []
    # This is still potentially large. Let's try another approach.
    # For n=4, we can just iterate over all C \subseteq \mathcal{P}(\{1, \dots, n\}).
    # There are 2^15 = 32768 such C.

    max_k = 0
    for i in range(1, 1 << len(subsets)):
        C = []
        for j in range(len(subsets)):
            if (i >> j) & 1:
                C.append(subsets[j])

        # A = {c^c : c \in C}
        # A_set = set of complements of elements in C
        A_set = set()
        for c in C:
            comp = frozenset([j for j in range(n) if j not in c])
            if comp: # exclude empty set
                A_set.add(comp)

        # G(A) = {y : y is not a subset of any c in C}
        G_A_count = 0
        for y in subsets:
            is_in_G = True
            for c in C:
                if y.issubset(c):
                    is_in_G = False
                    break
            if is_in_G:
                G_A_count += 1

        # |A \cap G(A)| = count of x in A_set such that x is not a subset of any c in C
        A_cap_G_count = 0
        for x in A_set:
            is_in_G = True
            for c in C:
                if x.issubset(c):
                    is_in_G = False
                    break
            if is_in_G:
                A_cap_G_count += 1

        k = min(len(A_set), G_A_count - A_cap_G_count)
        if k > max_k:
            max_k = k

    return max_k

